(()=>{const A=Abibi,page=document.body.dataset.page;function stats(){return [['امتیاز قابل استفاده',A.fa(A.state.points),'points.html','گردش امتیاز'],['سطح عضویت',A.tier().current.name,'levels.html','مسیر ارتقا'],['سفارش‌ها',A.fa(A.state.orders.length),'orders.html','مشاهده سفارش‌ها'],['کوپن‌های من',A.fa(A.state.coupons.length),'coupons.html','استفاده از پاداش‌ها']].map(([label,value,href,link])=>`<div class="col-6 col-xl-3"><div class="stat-card"><small>${label}</small><strong class="metric">${value}</strong><a href="${href}">${link} ←</a></div></div>`).join('')}
function addresses(){A.$('#address-list').innerHTML=A.state.addresses.length?A.state.addresses.map(x=>`<div class="col-md-6"><article class="surface h-100"><h2 class="h6">⌖ ${A.esc(x.title)}</h2><p class="small text-muted">${A.esc(x.text)}</p><div class="d-flex gap-2"><button class="btn btn-outline-primary btn-sm" data-edit-address="${x.id}">ویرایش</button><button class="btn btn-light btn-sm" data-delete-address="${x.id}">حذف</button></div></article></div>`).join(''):'<div class="col-12"><p class="notice">هنوز آدرسی ذخیره نکرده‌ای. اولین آدرس را در فرم زیر اضافه کن.</p></div>'}
if(page==='dashboard'){A.$('#dashboard-stats').innerHTML=stats();const o=A.state.orders[0];A.$('#latest-order').innerHTML=o?`<span class="badge text-bg-light">سفارش نمایشی</span><h3 class="h6 my-3" dir="ltr">AB-${A.esc(o.number)}</h3><p class="small text-muted">${A.date(o.date)}</p>${A.money(o.total)}<a href="order-detail.html?id=${o.id}" class="btn btn-outline-primary w-100 mt-3">جزئیات و پیگیری</a>`:A.empty('اولین سفارشت منتظرته','از منوی آبی‌بی شروع کن.');const t=A.tier();A.$('#dashboard-level').innerHTML=`<p class="small text-muted mt-3">سطح فعلی: ${t.current.name}</p><div class="progress" role="progressbar" aria-label="پیشرفت سطح" aria-valuenow="${Math.round(t.percent)}" aria-valuemin="0" aria-valuemax="100"><div class="progress-bar" style="width:${t.percent}%"></div></div><p class="level-note">${t.next?A.fa(t.remaining)+' امتیاز سطح تا '+t.next.name:'بالاترین سطح باشگاه'}</p>`;A.$('#dashboard-level').previousElementSibling.textContent=t.next?'قدم بعدی، عضویت '+t.next.name:'در بالاترین سطح باشگاه'}
if(page==='profile'){const f=A.$('#profile-form');for(const [n,v]of Object.entries(A.state.profile))if(f.elements[n])f.elements[n].value=v;f.addEventListener('submit',e=>{e.preventDefault();let phone=A.digits(f.elements.phone.value).replace(/[\s-]/g,'');if(phone&&!/^09\d{9}$/.test(phone)){A.toast('شماره موبایل معتبر وارد کن');return}if(f.elements.birthday.value&&new Date(f.elements.birthday.value)>new Date()){A.toast('تاریخ تولد نمی‌تواند در آینده باشد');return}A.state.profile={name:f.elements.name.value.trim()||'مهمان آبی‌بی',phone,email:f.elements.email.value.trim(),birthday:f.elements.birthday.value};A.save();A.toast('اطلاعات در همین مرورگر ذخیره شد')})}
if(page==='addresses'){addresses();const f=A.$('#address-form');f.addEventListener('submit',e=>{e.preventDefault();const data={id:f.elements.id.value||A.id(),title:f.elements.title.value.trim(),text:f.elements.text.value.trim()};if(!data.title||data.text.length<10){A.toast('عنوان و آدرس کامل را وارد کن');return}const i=A.state.addresses.findIndex(x=>x.id===data.id);i<0?A.state.addresses.push(data):A.state.addresses.splice(i,1,data);A.save();f.reset();addresses();A.toast('آدرس ذخیره شد')});f.addEventListener('reset',()=>{f.elements.id.value='';A.$('#address-form-title').textContent='افزودن آدرس'});document.addEventListener('click',e=>{const edit=e.target.closest('[data-edit-address]');if(edit){const x=A.state.addresses.find(x=>x.id===edit.dataset.editAddress);if(x){for(const[n,v]of Object.entries(x))f.elements[n].value=v;A.$('#address-form-title').textContent='ویرایش آدرس';f.elements.title.focus()}}const del=e.target.closest('[data-delete-address]');if(del&&confirm('این آدرس حذف شود؟')){A.state.addresses=A.state.addresses.filter(x=>x.id!==del.dataset.deleteAddress);if(f.elements.id.value===del.dataset.deleteAddress)f.reset();A.save();addresses()}})}
if(page==='login'){let phone='';A.$('#login-form').addEventListener('submit',e=>{e.preventDefault();phone=A.digits(A.$('#login-phone').value).replace(/[\s-]/g,'');if(!/^09\d{9}$/.test(phone)){A.toast('شماره موبایل ۱۱ رقمی با ۰۹ وارد کن');return}A.$('#login-form').hidden=true;A.$('#verify-form').hidden=false;A.$('#demo-code').focus()});A.$('#verify-form').addEventListener('submit',e=>{e.preventDefault();if(A.digits(A.$('#demo-code').value)!=='1234'){A.toast('برای نمایش قالب، کد ۱۲۳۴ را وارد کن');return}A.state.profile.phone=phone;A.save();location.href='dashboard.html'})}})();
